scripts.build:
wasm-pack build --target web ../../crates/hce-wasm && cp ../../crates/hce-wasm/pkg/hce_wasm_bg.wasm ./index_bg.wasm && cp ../../crates/hce-wasm/pkg/hce_wasm.js ./index.web.js && cp ../../crates/hce-wasm/pkg/hce_wasm.d.ts ./index.web.d.ts && cp ../../crates/hce-wasm/pkg/hce_wasm_bg.wasm.d.ts ./index_bg.wasm.d.ts && python3 -c "import base64; b=open('index_bg.wasm','rb').read(); c=base64.b64encode(b).decode(); chunks=[c[i:i+120] for i in range(0,len(c),120)]; js='import { initSync, HceCodec } from "./index.web.js";
const B64=['+','.join(f'"{x}"' for x in chunks)+'].join("");
const w=Uint8Array.from(atob(B64),c=>c.charCodeAt(0));
initSync(w);
export { HceCodec };
'; open('index.node.js','w').write(js);"
